  "dl.f.voice.text": "Jubla, klaga och reta varandra medan ni draftar. Man ser vem som pratar.",
  "dl.f.ai.title": "AI-klubbar",
  "dl.f.ai.text": "Bara två? Fyll ligan med AI-klubbar som draftar och spelar själva.",
  "dl.f.keepers.title": "Keepers",
  "dl.f.keepers.text": "Behåll 0-3 spelare från förra säsongen. Bygg en dynasti – eller börja om varje år.",
  "dl.f.playoff.title": "Slutspel",
  "dl.f.playoff.text": "Avsluta säsongen med en final eller semifinaler. Enkelmatcher, förlängning och straffar.",
  "dl.f.today.title": "Allt i dag",
  "dl.f.today.text": "Inga datum och ingen trötthet som hänger kvar. Spela en hel säsong på en kväll.",
  "dl.f.finale.title": "Säsongsavslutning",
  "dl.f.finale.text": "Mästare, skyttekung, assists och bästa betyg – plus maratontabell över säsongerna.",
  "dl.f.crest.title": "Ditt eget emblem",
  "dl.f.crest.text": "Välj form och färger. Klubben bär dina färger hela vägen.",
  "dl.f.fair.title": "Rättvist för alla",
  "dl.f.fair.text": "Ingen kemi, moral eller pengar. Bara dina val och din taktik avgör.",
  "dl.shotsTitle": "Se det i action",
  "dl.shotsSub": "Från lobby till mästare – allt i webbläsaren.",
  "dl.shot.lobby": "Lobbyn",
  "dl.shot.lobby.text": "Skapa din klubb, bjud in vänner och chatta medan ni väntar.",
  "dl.shot.live": "Live-draften",
  "dl.shot.live.text": "Klockan, poolen, din plan och draft-tavlan.",
  "dl.shot.summary": "Avslutningen",
  "dl.shot.summary.text": "Sluttabellen och säsongens bästa – och sedan vidare till nästa draft.",
  "dl.finalTitle": "Vem har bäst öga för en spelare?",
  "dl.finalText": "Skapa en liga, skicka länken till dina vänner och ta reda på det i kväll.",
  "land.promoPill": "Ny speltyp",
  "land.promoTitle": "Draftliga: drafta ditt drömlag med vännerna",
  "land.promoText": "Bygg en fiktiv klubb av de 500 bästa spelarna – live, med 60 sekunder per val och röstchatt. Spela sedan en hel säsong mot varandra på en kväll.",
  "land.promoCta": "Läs om draftligan",
  "dr.grade.A+.1": "Det här är ingen draft, det är ett rån. Alla andra kan lika gärna spela om andraplatsen.",
  "dr.grade.A+.2": "Experten har inga fler superlativ. Ett lag byggt av någon som har sett FÖR mycket fotboll.",
  "dr.grade.A+.3": "Favoriterna. Om de inte vinner är det managerns fel – inte draftens.",
  "dr.grade.A.1": "Stark draft med mycket få svaga punkter. Resten av ligan bör vara nervösa.",
  "dr.grade.A.2": "Klassiskt, solitt och farligt. En av de få som faktiskt hade en plan.",
  "dr.grade.A.3": "Toppklass hela vägen ner. Bara bänken skiljer dem från ett A+.",
  "dr.grade.B+.1": "Bra jobbat. Ett par val som experten rynkar på näsan åt, men helheten håller.",
  "dr.grade.B+.2": "Över medel och med potential för överraskningar. Underskatta dem på egen risk.",
  "dr.grade.B+.3": "Stjärnorna finns där – nu behöver bara taktiken hänga med.",
  "dr.grade.B.1": "Varken hett eller kallt. Ett lag man glömmer tills de tar poäng av en.",
  "dr.grade.B.2": "Mitt i klungan. Säsongen avgörs av taktiken, inte av draften.",
  "dr.grade.B.3": "Gediget hantverk utan stora gester.",
  "dr.grade.C.1": "Experten kliade sig i nacken flera gånger på vägen. Det finns hål.",
  "dr.grade.C.2": "Några bra namn, men också val som fick chatten att gå bananas.",
  "dr.grade.C.3": "Det kan gå – om allt går ihop. Det gör det sällan.",
  "dr.grade.D.1": "Var det här en draft eller ett lyckohjul? Experten är orolig.",
  "dr.grade.D.2": "Tidiga val som borde ha tagits mycket senare. Eller inte alls.",
  "dr.grade.D.3": "Underdoglaget. Till gengäld kan man bara överraska positivt.",
  "dr.grade.F.1": "Experten har blundat och dragit ur sladden. Lycka till.",
  "dr.grade.F.2": "Var assistenten på semester? Det här kräver ett mirakel.",
  "dr.grade.F.3": "Historiskt dåligt. Men det står inget i reglerna om att man inte kan vinna ändå.",
  "dr.gradesTitle": "Experten bedömer draften",
