  "trophy.board.league": "Styrelsen hyllar {manager}: {club} är mästare!",
  "trophy.board.league.body": "Ordföranden: \"Det här är en historisk dag för {club}. {manager} har gett oss det vi drömt om – ett mästerskap. Styrelsen står 100 % bakom dig, och vi ser redan fram emot nästa säsong.\"",
  "trophy.board.leagueAgain": "Styrelsen: {manager} gör det igen – mästerskap nr {n}!",
  "trophy.board.leagueAgain.body": "Ordföranden: \"Att vinna en gång är stort. Att göra det om och om igen är en era. Tack, {manager} – du har gjort {club} till en dynasti.\"",
  "trophy.board.cup": "Styrelsen gratulerar till {comp}!",
  "trophy.board.cup.body": "Ordföranden: \"En pokal i skåpet – det är precis sådana kvällar vi gör det här för. Stort grattis till {manager} och hela truppen.\"",
  "trophy.board.cupAgain": "Styrelsen: {comp} igen – titel nr {n} under {manager}!",
  "trophy.board.cupAgain.body": "Ordföranden: \"Det börjar bli en vana, och det är en bra vana. Grattis, {manager}.\"",
  "trophy.board.europe": "Europeisk triumf! Styrelsen är i extas över {comp}",
  "trophy.board.europe.body": "Ordföranden: \"{club} har vunnit {comp}. Det är den största kvällen i klubbens nyare historia. {manager}, ditt namn står nu i klubbens historieböcker för evigt.\"",
  "trophy.board.europeAgain": "Styrelsen: {comp} igen – {manager} är en legend!",
  "trophy.board.europeAgain.body": "Ordföranden: \"Titel nr {n} i {comp}. Det finns inga ord. Tack.\"",
  "trophy.fans.league": "Staden går bananas – tusentals fans firar mästerskapet",
  "trophy.fans.league.body": "Gatorna är fulla av {club}-tröjor, flaggor och fyrverkerier. I fanforumet heter det bara en sak: \"{manager}, {manager}, {manager}!\"",
  "trophy.fans.cup": "Fansen firar {comp}-segern hela natten",
  "trophy.fans.cup.body": "Läktaren sjöng länge efter slutsignalen, och bussen med pokalen möttes av jublande fans utanför arenan.",
  "trophy.fans.europe": "Hela landet firar {club}s europeiska triumf",
  "trophy.fans.europe.body": "Tiotusentals fans tog emot laget på flygplatsen. \"Det här glömmer vi aldrig\", hörs det överallt.",
  "trophy.captain.league": "{player}: \"Det här är för dig och fansen, chefen\"",
  "trophy.captain.league.body": "Lagkaptenen: \"Du fick oss att tro på det från första dagen. Varenda en i omklädningsrummet skulle springa genom en vägg för dig. Tack, chefen.\"",
  "trophy.captain.cup": "{player}: \"Du gav oss tron i finalen\"",
  "trophy.captain.cup.body": "Lagkaptenen: \"Peppen före matchen satt som en smäck. Vi ville vinna den här för dig.\"",
  "trophy.captain.europe": "{player}: \"Den största kvällen i mitt liv – tack, chefen\"",
  "trophy.captain.europe.body": "Lagkaptenen: \"Som pojke drömde jag om att lyfta den här pokalen. Du gjorde det möjligt.\"",
  "trophy.press.league": "Tidningen: {manager} – arkitekten bakom {club}s mästerskap",
  "trophy.press.league.body": "Experterna är överens: taktiken, värvningarna och förmågan att få ut det bästa av truppen gjorde skillnaden. {manager} nämns redan som årets manager.",
  "trophy.press.cup": "Tidningen: {manager} levererar pokal till {club}",
