  "land.rankTitle": "Är du landets bästa manager?",
  "land.rankText": "Manager Score belönnar uppgiften, inte bara budgeten: placering mot förväntan, ligans styrka, titlar, Europa, ekonomi och unga spelare. Bara första försöket för varje säsong räknas.",
  "land.rankCta": "Starta din karriär",
