  "land.faqTitle": "Vanliga frågor",
  "land.q1": "Kostar det något?",
  "land.a1": "Nej. Spelet är gratis, och det finns inga reklamer eller köp i spelet.",
  "land.q2": "Måste jag installera något?",
  "land.a2": "Nej, det körs direkt i webbläsaren. Du kan installera det som app på mobil och dator, och det fungerar även offline.",
  "land.q3": "Var sparas mitt spel?",
  "land.a3": "Lokalt på din enhet – automatiskt, så du kan stänga fliken och fortsätta senare. Du kan också exportera och importera sparade spel.",
  "land.q4": "Är spelarna riktiga?",
  "land.a4": "Ja, över 40 000 riktiga spelare i två databaser: gemenskapens October 2026-uppdatering till CM 01/02 (22 700 spelare i säsongen 2026/27) och den ursprungliga CM 01/02-databasen från 2001/02 (35 000 spelare). Förmågorna kommer från CM-databaserna.",
  "land.q5": "Kan jag spela med mina vänner?",
  "land.a5": "Ja. Skapa ett onlinespel, dela koden och styr varsin klubb i samma värld.",
  "land.f.authentic.title": "Äkta CM 01/02-läge",
  "land.f.authentic.text": "2001 års regler, originalets kommentarer och ljud, Bosman-fria övergångar och den gamla databasen – eller det utökade läget med allt det nya.",
  "land.q7": "Kan jag spela med den ursprungliga databasen från 2001/02?",
  "land.a7": "Ja. Välj den ursprungliga CM 01/02-databasen (patch 3.9.60) när du startar ett nytt spel – med Tsigalko, Cherno Samba och de andra legenderna, slumpmässig potential och 2001 års regler. Eller spela säsongen 2026/27.",
  "land.q8": "Kan jag slå upp spelare och wonderkids?",
  "land.a8": "Ja. Båda databaserna kan bläddras på sajten: alla spelare med alla egenskaper, CA/PA, wonderkids, Bosman-fria övergångar och de bästa på varje position.",
